<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
import {agendaIssue,nextWeekly,type Agenda,type Weekly} from '../agendas';
const props=defineProps<{canManage:boolean;request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>}>();
const open=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),rows=ref<Agenda[]>([]),editing=ref<Agenda|null>(null),active=ref(false),interval=ref(60),mode=ref('intervalo'),days=ref<number[]>([]),time=ref('09:00'),zone=ref('America/Sao_Paulo');
let alive=true,generation=0,controller:AbortController|undefined;
const weekdays=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
const weekly=computed<Weekly|null>(()=>mode.value==='semanal'?{dias:[...new Set(days.value)].sort(),horario:time.value,fuso:zone.value.trim()}:null);
const issue=computed(()=>agendaIssue(interval.value,weekly.value));
const occurrence=computed(()=>weekly.value?nextWeekly(weekly.value,new Date()):null);
function date(value:Date,timezone?:string){return value.toLocaleString('pt-BR',{timeZone:timezone});}
function describe(row:Agenda){return row.semanal?`${row.semanal.dias.map(day=>weekdays[day]).join(', ')} · ${row.semanal.horario} · ${row.semanal.fuso}`:`A cada ${row.intervalo_minutos} minutos`;}
async function load(){const current=++generation;controller?.abort();controller=new AbortController();loading.value=true;error.value='';rows.value=[];try{const result=await props.request<Agenda[]>('/api/contexto/agendas','GET',undefined,controller.signal);if(alive&&current===generation)rows.value=result;}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
function show(){open.value=true;notice.value='';void load();}
function edit(row:Agenda){editing.value=row;error.value='';notice.value='';active.value=row.ativa;interval.value=row.intervalo_minutos;mode.value=row.semanal?'semanal':'intervalo';days.value=[...(row.semanal?.dias??[])];time.value=row.semanal?.horario??'09:00';zone.value=row.semanal?.fuso??'America/Sao_Paulo';}
function close(){if(busy.value)return;editing.value=null;open.value=false;generation++;controller?.abort();}
async function save(){if(!props.canManage||!editing.value||busy.value||issue.value)return;const current=generation;busy.value=true;error.value='';try{await props.request('/api/contexto/agendas/'+editing.value.monitoramento_id,'PUT',{ativa:active.value,intervalo_minutos:interval.value,semanal:weekly.value});if(!alive||current!==generation)return;editing.value=null;notice.value='Agenda salva.';await load();}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive)busy.value=false;}}
onBeforeUnmount(()=>{alive=false;generation++;controller?.abort();});
</script>
<template><button type="button" class="secondary" @click="show">Agendas de coleta</button>
<AppDialog v-if="open" title="Agendas de coleta" :busy="busy" @close="close"><template v-if="!editing"><p>Uma agenda por consulta sindical. O agendador cria solicitações; o processamento depende do worker e dos limites do escritório.</p><button type="button" class="secondary" :disabled="loading" @click="load">Atualizar agendas</button><p v-if="loading" role="status">Carregando agendas…</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="error" role="alert">{{ error }}</p><div v-if="!loading&&!error" class="registry-scroll"><table><caption>Agendas das consultas</caption><thead><tr><th scope="col">Consulta</th><th scope="col">Agenda</th><th scope="col">Situação</th><th v-if="canManage" scope="col">Ação</th></tr></thead><tbody><tr v-for="row in rows" :key="row.monitoramento_id"><td>{{ row.nome }}<p v-if="!row.monitoramento_ativo">Consulta inativa</p></td><td>{{ describe(row) }}</td><td>{{ row.ativa?'Ativa':'Inativa' }}</td><td v-if="canManage"><button type="button" class="secondary" :aria-label="'Configurar agenda de '+row.nome" @click="edit(row)">Configurar</button></td></tr><tr v-if="!rows.length"><td :colspan="canManage?4:3">Ainda não há consultas para agendar neste escritório.</td></tr></tbody></table></div></template>
<form v-else class="vue-form" @submit.prevent="save"><h3>{{ editing.nome }}</h3><fieldset class="agenda-fields" :disabled="busy"><label class="confirmation-check"><input v-model="active" type="checkbox" :disabled="!editing.monitoramento_ativo&&!active">Agenda ativa</label><p v-if="!editing.monitoramento_ativo">Consulta inativa: a agenda pode ser desativada, mas sua ativação exige reativar a consulta em Cadastros.</p><label>Modo da agenda<select v-model="mode"><option value="intervalo">Intervalo</option><option value="semanal">Dias da semana</option></select></label><label>Intervalo em minutos<input v-model.number="interval" type="number" min="60" max="10080" step="1" required></label><p v-if="mode==='semanal'">O intervalo fica preservado para o modo Intervalo; a agenda semanal usa os dias, horário e fuso abaixo.</p><template v-if="mode==='semanal'"><fieldset><legend>Dias da semana</legend><label v-for="(day,index) in weekdays" :key="index" class="confirmation-check"><input v-model="days" type="checkbox" :value="index">{{ day }}</label></fieldset><label>Horário da coleta<input v-model="time" type="time" required></label><label>Fuso horário<input v-model="zone" list="agenda-timezones" required maxlength="100"></label><datalist id="agenda-timezones"><option>America/Sao_Paulo</option><option>America/Manaus</option><option>America/Rio_Branco</option><option>America/Noronha</option><option>UTC</option></datalist><p v-if="occurrence">Próxima ocorrência no calendário: {{ date(occurrence,zone.trim()) }} ({{ zone.trim() }}).</p><p>A janela do dia selecionado permanece aberta após o horário. Uma execução já agendada ou pendente impede duplicação; o processamento pode ocorrer depois do horário previsto.</p></template><p v-else>As janelas de intervalo são alinhadas pelo relógio do servidor. Ao ativar, a janela atual já pode criar uma solicitação; não é uma contagem iniciada ao salvar.</p></fieldset><p v-if="issue" role="alert">{{ issue }}</p><p v-if="error" role="alert">{{ error }}</p><footer><button type="button" class="secondary" :disabled="busy" @click="editing=null;error=''">Voltar às agendas</button><button type="submit" class="primary" :disabled="busy||!!issue||(!editing.monitoramento_ativo&&active)">{{ busy?'Salvando…':'Salvar agenda' }}</button></footer></form></AppDialog></template>
<style scoped>.agenda-fields{display:grid;gap:12px;border:0;padding:0;min-width:0}.agenda-fields fieldset{min-width:0}.agenda-fields p{margin:0}.agenda-fields label{display:grid;gap:8px}.agenda-fields label.confirmation-check{display:flex}</style>
